// Des: Tests for secret refs: account book, limits, id rules
// Flo: scratch folder > write user-acct.json > load the book > pick accounts > status lists names only
// I/O: scratch dir (no real secrets) > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-secr-refs-test.zig
// ===================================================================
const std = @import("std"); const secr = @import("ru-secr-refs.zig"); const cfgz = @import("cf-conf-load.zig");
fn dirOf(tmp: *std.testing.TmpDir, aren: std.mem.Allocator) ![]u8 { return std.fmt.allocPrint(aren, ".zig-cache/tmp/{s}", .{tmp.sub_path}); }
fn put(tmp: *std.testing.TmpDir, aren: std.mem.Allocator, data: []const u8) ![]u8 { const dir = try dirOf(tmp, aren); try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(aren, "{s}/user-acct.json", .{dir}), .data = data }); return dir; }
test "the old flat file is one account called main; unknown fields are ignored" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const dir = try put(&tmp, aren.allocator(), "{\"login\":\"a@b.test\",\"pass\":\"pw-secret-1\",\"zzzz\":1}"); const book = try secr.loadBook(aren.allocator(), std.testing.io, dir, 5); try std.testing.expectEqual(@as(usize, 1), book.accs.len); try std.testing.expectEqualStrings("main", book.main); const acc = secr.pick(book, "").?; try std.testing.expectEqualStrings("a@b.test", acc.login); try std.testing.expectEqual(@as(u32, 2), secr.countAcc(acc)); try std.testing.expectEqualStrings("pw-secret-1", secr.toSecr(acc).pass); }
test "a book with several accounts: pick by id, main defaults to the first, lang and caps percent are read" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const dir = try put(&tmp, aren.allocator(), "{\"v\":1,\"accs\":[{\"id\":\"shop1\",\"login\":\"a@x.test\",\"pass\":\"p1\"},{\"id\":\"shop2\",\"login\":\"b@x.test\",\"pass\":\"p2\",\"lang\":\"en\",\"scal\":50}]}"); const book = try secr.loadBook(aren.allocator(), std.testing.io, dir, 5); try std.testing.expectEqual(@as(usize, 2), book.accs.len); try std.testing.expectEqualStrings("shop1", book.main); try std.testing.expectEqualStrings("b@x.test", secr.pick(book, "shop2").?.login); try std.testing.expectEqualStrings("en", secr.pick(book, "shop2").?.lang); try std.testing.expectEqual(@as(u32, 50), secr.pick(book, "shop2").?.scal); try std.testing.expect(secr.pick(book, "nope") == null); try std.testing.expectEqualStrings("a@x.test", secr.pick(book, "").?.login); }
test "bad books are rejected: repeated id, bad id, too many accounts, unknown main, caps percent out of range, broken JSON" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const bads = [_][]const u8{ "{\"accs\":[{\"id\":\"a\"},{\"id\":\"a\"}]}", "{\"accs\":[{\"id\":\"Bad Id\"}]}", "{\"accs\":[{\"id\":\"\"}]}", "{\"accs\":[{\"id\":\"a\"},{\"id\":\"b\"},{\"id\":\"c\"}]}", "{\"main\":\"zz\",\"accs\":[{\"id\":\"a\"}]}", "{\"accs\":[{\"id\":\"a\",\"scal\":0}]}", "{\"accs\":[{\"id\":\"a\",\"scal\":101}]}", "not json" }; for (bads) |txt| { const dir = try put(&tmp, aren.allocator(), txt); try std.testing.expectError(error.BadConfig, secr.loadBook(aren.allocator(), std.testing.io, dir, 2)); } }
test "a missing folder or file gives one empty account main, never an error" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const dir = try dirOf(&tmp, aren.allocator()); const b1 = try secr.loadBook(aren.allocator(), std.testing.io, dir, 5); try std.testing.expect(!b1.filez); try std.testing.expectEqual(@as(usize, 1), b1.accs.len); try std.testing.expectEqual(@as(u32, 0), secr.countAcc(b1.accs[0])); const b2 = try secr.loadBook(aren.allocator(), std.testing.io, "no-such-folder-zz", 5); try std.testing.expectEqualStrings("main", b2.main); const b3 = try secr.loadBook(aren.allocator(), std.testing.io, "", 5); try std.testing.expectEqual(@as(usize, 1), b3.accs.len); }
test "id rules: lower-case letters, digits and dash, 1 to 16 characters" { try std.testing.expect(secr.idOk("shop-1")); try std.testing.expect(secr.idOk("a")); try std.testing.expect(!secr.idOk("")); try std.testing.expect(!secr.idOk("Shop")); try std.testing.expect(!secr.idOk("a b")); try std.testing.expect(!secr.idOk("this-id-is-way-too-long")); try std.testing.expect(!secr.idOk("../x")); }
test "the secrets folder comes from config and expands the home folder" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf: cfgz.Conf = .{}; const dir = try secr.dirOf(aren.allocator(), "/home/u", conf); try std.testing.expectEqualStrings("/home/u/.zz-base-home-secr/as-apps/ch-chat/fb-face-webs", dir); }
